lab.solution:
class ProgressImportError(Exception):
    pass

def parse_minutes(text):
    try:
        minutes = int(text)
    except ValueError as error:
        raise ProgressImportError('minutes must be a whole number') from error
    if minutes < 0:
        raise ProgressImportError('minutes must not be negative')
    return minutes

for text in ['25', 'two', '-1']:
    try:
        print(parse_minutes(text))
    except ProgressImportError as error:
        print(error)

lab.testCode:
assert parse_minutes('25') == 25
for bad in ('two', '-1'):
    try:
        parse_minutes(bad)
    except ProgressImportError:
        pass
    else:
        raise AssertionError('invalid minutes accepted')
print('PASS: valid and invalid minute records')
